   */
  i18n?: I18NConfig | null

  /**
   * @see [Next.js TypeScript documentation](https://nextjs.org/docs/app/api-reference/config/typescript)
   */
  typescript?: TypeScriptConfig

  /**
   * Enable type checking for Link and Router.push, etc.
   * This feature requires TypeScript in your project.
   *
   * @see [Typed Links documentation](https://nextjs.org/docs/app/api-reference/config/typescript#statically-typed-links)
   */
  typedRoutes?: boolean

  /**
   * Headers allow you to set custom HTTP headers for an incoming request path.
   *
   * @see [Headers configuration documentation](https://nextjs.org/docs/app/api-reference/config/next-config-js/headers)
   */
  headers?: () => Promise<Header[]> | Header[]

  /**
   * Rewr
... 607049 bytes omitted ...
h: string,
  fallbackRouteParams: OpaqueFallbackRouteParams | null,
  renderOpts: RenderOpts
): AppPagePreparation {
  if (!requestUrl) {
    throw new Error('Invalid URL')
  }

  const url = parseRelativeUrl(requestUrl, undefined, false)

  const interpolatedParams = interpolateParallelRouteParams(
    renderOpts.ComponentMod.routeModule.userland.loaderTree,
    renderOpts.params ?? {},
    pagePath,
    fallbackRouteParams
  )

  // If provided, the postpone state should be parsed so it can be provided to
  // React.
  let postponedState: PostponedState | null = null
  if (typeof renderOpts.postponed === 'string') {
    if (fallbackRouteParams) {
      if (!serverActionRequestMetadata.isFetchAction) {
        throw new InvariantError(
          'postponed state should not be provided when fallback params are provided'
        )
      }

      // A fetch action with fallback params cannot render this page, so its
      // React postponed state cannot be resumed. The RDC is still useful while
      // executing cached functions in the action.
      postponedState = {
        type: DynamicState.DATA,
        renderResumeDataCache: parseResumeDataCacheFromPostponedState(
          renderOpts.postponed,
          renderOpts.experimental.maxPostponedStateSizeBytes,
          renderOpts.experimental.disableResumeDataCacheCompression
        ),
      }
    } else {
      postponedState = parsePostponedState(
        renderOpts.postponed,
        renderOpts.experimental.maxPostponedStateSizeBytes,
        renderOpts.experimental.disableResumeDataCacheCompression
      )
    }
  }

  if (
    postponedState?.renderResumeDataCache &&
    renderOpts.renderResumeDataCache
  ) {
    throw new InvariantError(
      'postponed state and dev warmup immutable resume data cache should not be provided together'
    )
  }

  return {
    url,
    interpolatedParams,
    postponedState,
  }
}

